using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class GreetingTools
{
    [McpServerTool, Description("Returns a greeting for the given name.")]
    public static string Greet([Description("The name to greet")] string name)
    {
        return $"Hello, {name}! Welcome to the MCP HTTP server.";
    }

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime()
    {
        return DateTime.UtcNow.ToString("o");
    }
}

using ModelContextProtocol.Server;
using System.Text.Json;

namespace McpHttpServer;

public class ConfigResourceProvider
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["version"] = "1.0.0",
        ["environment"] = "development",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        },
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30
    };

    [McpServerResource("config://app", Name = "Application Configuration",
        Description = "Returns the current application configuration as JSON.",
        MimeType = "application/json")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }

    [McpServerResource("config://app/{section}", Name = "Configuration Section",
        Description = "Returns a specific section of the application configuration.",
        MimeType = "application/json")]
    public static string GetConfigSection(string section)
    {
        if (AppConfig.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value, new JsonSerializerOptions
            {
                WriteIndented = true
            });
        }

        return JsonSerializer.Serialize(new { error = $"Section '{section}' not found." });
    }
}

